using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

namespace KspContinuum.Tools;

internal static class ChronicleCommand
{
    public static int Run(string[] args)
    {
        var options = new Arguments(args);
        var mission = Path.GetFullPath(options.Required("--mission"));
        var inputs = options.Optional("--inputs") is { } value ? Path.GetFullPath(value) : null;
        var output = Path.GetFullPath(options.Required("--output"));
        var metadata = Tooling.ReadObject(options.Required("--metadata"), 256 * 1024);
        Tooling.Require(Directory.Exists(mission), "mission directory does not exist");
        Tooling.Require(!Directory.Exists(output) && !File.Exists(output), "output already exists");
        Tooling.Require(metadata["schema"]?.ToString() == "ksp-continuum-chronicle-metadata/v1", "unsupported metadata schema");
        var missionId = Field(metadata, "mission_id"); var attempt = Field(metadata, "attempt_id"); var vehicle = Field(metadata, "vehicle_design_id"); var title = Field(metadata, "name", 500);
        Tooling.Require(attempt.StartsWith(missionId + "-A", StringComparison.Ordinal), "attempt_id must belong to mission_id");
        var receipt = ParseReceipt(Path.Combine(mission, "mission.txt")); MatchReceipt(receipt, "missionId", missionId, "mission_id"); MatchReceipt(receipt, "attemptId", attempt, "attempt_id"); MatchReceipt(receipt, "vehicleDesignId", vehicle, "vehicle_design_id");
        var site = metadata["site_id"]?.GetValue<string>(); MatchReceipt(receipt, "siteId", site, "site_id");
        var outcome = receipt.GetValueOrDefault("status") ?? throw new ToolException("mission receipt has no status"); var inputEvidence = ValidateInputs(receipt, inputs); var telemetry = ParseMissionTelemetry(Path.Combine(mission, "mission.csv")); var captures = ParseCaptures(mission);
        var staging = output + ".tmp-" + Guid.NewGuid().ToString("N"); Directory.CreateDirectory(staging);
        try
        {
            var sourceEntries = SourceEntries(mission, "mission"); if (inputs is not null) foreach (var item in SourceEntries(inputs, "inputs")) sourceEntries.Add(item?.DeepClone());
            var mediaEntries = new JsonArray(); foreach (var capture in captures) { var source = Path.Combine(mission, capture.Name); if (capture.Confirmed && File.Exists(source)) { var media = Path.Combine(staging, "media"); Directory.CreateDirectory(media); File.Copy(source, Path.Combine(media, capture.Name)); } mediaEntries.Add(new JsonObject { ["filename"] = capture.Name, ["status"] = capture.Status, ["width"] = capture.Width, ["height"] = capture.Height }); }
            File.WriteAllText(Path.Combine(staging, "index.html"), Render(metadata, attempt, outcome, telemetry, captures, receipt), new UTF8Encoding(false));
            var playbackData = MissionPlayback(Path.Combine(mission, "mission.csv"), telemetry); var playback = TelemetryPlayerCommand.Render(playbackData, title + " — recorded telemetry", true); File.WriteAllText(Path.Combine(staging, "telemetry.html"), playback, new UTF8Encoding(false));
            var manifest = new JsonObject { ["schema"] = "ksp-continuum-chronicle-manifest/v1", ["templateVersion"] = "mission-v1", ["missionId"] = missionId, ["attemptId"] = attempt, ["attemptAlias"] = attempt, ["vehicleDesignId"] = vehicle, ["siteId"] = site, ["title"] = title, ["outcome"] = outcome, ["generatedUtc"] = DateTimeOffset.UtcNow.ToString("O"), ["report"] = "index.html", ["templateSha256"] = Tooling.Sha256(Path.Combine(Tooling.Root(), "templates/chronicle/mission-v1.html")), ["generatorSha256"] = Tooling.Sha256(typeof(ChronicleCommand).Assembly.Location), ["sourceSessions"] = new JsonObject { ["mission"] = Path.GetFileName(mission), ["inputs"] = inputs is null ? null : Path.GetFileName(inputs) }, ["inputEvidence"] = inputEvidence, ["sources"] = sourceEntries, ["media"] = mediaEntries, ["telemetryPlayback"] = new JsonObject { ["schema"] = "ksp-continuum-telemetry-playback/v1", ["report"] = "telemetry.html", ["rows"] = telemetry.Count, ["sourceSha256"] = playbackData["sourceSha256"]!.DeepClone(), ["sha256"] = Sha256Text(playback) } };
            foreach (var pair in new[] { ("parentAttemptId", "parent_attempt_id"), ("parentCheckpoint", "parent_checkpoint"), ("parentCheckpointSha256", "parent_checkpoint_sha256") }) manifest[pair.Item1] = metadata[pair.Item2]?.DeepClone();
            File.WriteAllText(Path.Combine(staging, "manifest.json"), manifest.ToJsonString(Tooling.Json) + "\n", new UTF8Encoding(false)); Directory.Move(staging, output); Console.WriteLine("Wrote mission chronicle to " + output); return 0;
        }
        catch { if (Directory.Exists(staging)) Directory.Delete(staging, true); throw; }
    }
    private static string Field(JsonObject data, string key, int maximum = 128) => Tooling.Text(data[key], key, maximum);
    private static Dictionary<string, string> ParseReceipt(string path) { var result = new Dictionary<string, string>(StringComparer.Ordinal); foreach (var line in Tooling.ReadBounded(path, 1024 * 1024).Split('\n', StringSplitOptions.RemoveEmptyEntries)) { var split = line.IndexOf('='); if (split > 0) result[line[..split]] = line[(split + 1)..].TrimEnd('\r'); } return result; }
    private static void MatchReceipt(Dictionary<string, string> receipt, string key, string? value, string label) { if (receipt.TryGetValue(key, out var actual)) Tooling.Require(actual == value, label + " does not match mission receipt"); else if (key == "siteId") Tooling.Require(value is null, "site_id does not match mission receipt"); }
    private static JsonObject ValidateInputs(Dictionary<string, string> receipt, string? inputs) { if (inputs is null) return new JsonObject { ["status"] = "not-supplied" }; Tooling.Require(Directory.Exists(inputs), "input directory does not exist"); Tooling.Require(receipt.TryGetValue("inputDirectory", out var declared), "mission does not declare inputDirectory"); var normalized = declared!.Replace('\\', '/').TrimEnd('/'); Tooling.Require(Path.GetFileName(normalized) == Path.GetFileName(inputs), "input directory does not match mission receipt"); return new JsonObject { ["status"] = "supplied", ["segments"] = Directory.EnumerateFiles(inputs, "segment-*.csv").Count() }; }
    private sealed record Capture(string Name, bool Confirmed, string Status, int? Width, int? Height);
    private static List<Capture> ParseCaptures(string mission) { var path = Path.Combine(mission, "screenshots.csv"); var result = new Dictionary<string, Capture>(StringComparer.Ordinal); if (!File.Exists(path)) return []; foreach (var line in File.ReadLines(path)) { var fields = line.Split(','); Tooling.Require(fields.Length is 3 or 5, "malformed screenshot receipt"); var name = fields[2]; Tooling.Require(Tooling.SafeRelative(name) && Path.GetFileName(name) == name, "unsafe screenshot filename"); var confirmed = fields[1] is "png-written" or "png-below-required-resolution"; int? width = fields.Length == 5 ? int.Parse(fields[3], CultureInfo.InvariantCulture) : null; int? height = fields.Length == 5 ? int.Parse(fields[4], CultureInfo.InvariantCulture) : null; result[name] = new(name, confirmed, fields[1], width, height); } return result.Values.ToList(); }
    private static JsonArray SourceEntries(string folder, string logicalRoot) { var result = new JsonArray(); foreach (var path in Directory.EnumerateFiles(folder).Order()) { var info = new FileInfo(path); Tooling.Require(info.LinkTarget is null, "source file may not be a symbolic link"); Tooling.Require(info.Length <= 32 * 1024 * 1024, "file exceeds size limit"); result.Add(new JsonObject { ["path"] = logicalRoot + "/" + info.Name, ["bytes"] = info.Length, ["sha256"] = Tooling.Sha256(path) }); } return result; }
    private static JsonArray ParseMissionTelemetry(string path) { var lines = Tooling.ReadBounded(path, 32 * 1024 * 1024).Replace("\r\n", "\n").TrimEnd('\n').Split('\n'); const string expected = "wall_s,ut_s,phase,body,situation,altitude_m,apoapsis_m,periapsis_m,surface_speed_mps,throttle,stage,parts,packed,autopilot"; Tooling.Require(lines.Length > 1 && lines[0] == expected, "unsupported mission.csv header"); var rows = new JsonArray(); double priorWall = -1, priorUt = -1; foreach (var line in lines.Skip(1)) { var f = line.Split(','); Tooling.Require(f.Length == 14, "malformed mission telemetry"); var wall = double.Parse(f[0], CultureInfo.InvariantCulture); var ut = double.Parse(f[1], CultureInfo.InvariantCulture); Tooling.Require(double.IsFinite(wall) && double.IsFinite(ut) && wall >= priorWall && ut >= priorUt, "telemetry clock moved backward"); priorWall = wall; priorUt = ut; rows.Add(new JsonObject { ["wall"] = wall, ["ut"] = ut, ["phase"] = f[2], ["body"] = f[3], ["situation"] = f[4], ["altitude"] = OptionalNumber(f[5]), ["speed"] = OptionalNumber(f[8]), ["throttle"] = OptionalNumber(f[9]), ["stage"] = OptionalNumber(f[10]), ["parts"] = OptionalNumber(f[11]), ["packed"] = f[12] == "" ? null : f[12] == "True", ["autopilot"] = f[13].Trim('"') }); } return rows; }
    private static JsonNode? OptionalNumber(string value) => value.Length == 0 ? null : JsonValue.Create(double.Parse(value, CultureInfo.InvariantCulture));
    private static JsonObject MissionPlayback(string path, JsonArray rows) => new() { ["schema"] = "ksp-continuum-telemetry-playback/v1", ["sourceSha256"] = Tooling.Sha256(path), ["rows"] = rows.DeepClone(), ["scope"] = "recorded observations only; no state reconstruction or resimulation" };
    private static string Render(JsonObject metadata, string attempt, string outcome, JsonArray telemetry, List<Capture> captures, Dictionary<string, string> receipt) { var first = telemetry[0]!["wall"]!.GetValue<double>(); var last = telemetry[^1]!["wall"]!.GetValue<double>(); var media = string.Join("", captures.Select(c => c.Confirmed ? $"<figure class=\"media\"><a href=\"media/{Tooling.Html(c.Name)}\"><img src=\"media/{Tooling.Html(c.Name)}\"></a><figcaption>{Tooling.Html(c.Name)} · {Tooling.Html(c.Status)}{(c.Width is null ? "" : $" · {c.Width} × {c.Height}")}</figcaption></figure>" : $"<p>{Tooling.Html(c.Name)}: Capture remained unconfirmed</p>")); var reason = receipt.GetValueOrDefault("reason") ?? ""; if (Regex.IsMatch(reason, @"(?:/Users/|/private/|[A-Za-z]:\\)")) reason = "redacted local path"; return $"<!doctype html><html><head><meta charset=\"utf-8\"><title>{Tooling.Html(metadata["name"]?.ToString())}</title><style>.media figcaption {{ padding-top: 10px; overflow-wrap: anywhere; }}</style></head><body><main><p>{Tooling.Html(attempt)}</p><h1>{Tooling.Html(metadata["name"]?.ToString())}</h1><p>Recorded outcome: <strong>{Tooling.Html(outcome)}</strong></p><section id=\"mission\"><h2>Mission</h2><p>{Tooling.Html(metadata["objective"]?.ToString())}</p><p>{Tooling.Html(reason)}</p></section><section id=\"timeline\"><h2>Timeline</h2><p>{last - first:0.00} s</p></section><section id=\"flight\"><h2>Flight</h2><a href=\"telemetry.html\">Recorded telemetry playback</a></section><section id=\"evidence\"><h2>Evidence</h2><div class=\"grid media-grid\">{media}</div></section><section id=\"engineering\"><h2>Engineering</h2><p>{Tooling.Html(metadata["next_experiment"]?.ToString())}</p></section></main></body></html>"; }
    private static string Sha256Text(string text) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant();
}

internal static class ChronicleIndexCommand
{
    public static int Run(string[] args) { var a = new Arguments(args, "--refresh"); var archive = Path.GetFullPath(a.Required("--archive")); var name = a.Required("--output"); Tooling.Require(Regex.IsMatch(name, @"^[A-Za-z0-9][A-Za-z0-9._-]*\.html$"), "output must be an HTML filename inside the archive"); var output = Path.Combine(archive, name); Tooling.Require(a.Has("--refresh") || !File.Exists(output), "output already exists; choose a new index filename"); var cards = new List<string>(); foreach (var versions in Reports(archive).GroupBy(x => x.Data["attemptId"]!.ToString())) { var latest = versions.OrderByDescending(x => DateTimeOffset.Parse(x.Data["generatedUtc"]!.ToString(), CultureInfo.InvariantCulture)).First(); var relative = Path.GetRelativePath(archive, latest.Folder).Replace(Path.DirectorySeparatorChar, '/'); cards.Add($"<article><p>{Tooling.Html(versions.Key)}</p><h2><a href=\"{relative}/index.html\">{Tooling.Html(latest.Data["title"]?.ToString())}</a></h2><p>Recorded outcome: <strong>{Tooling.Html(latest.Data["outcome"]?.ToString())}</strong></p></article>"); } Tooling.Require(cards.Count > 0, "archive has no generated reports"); var page = Tooling.ReadBounded(Path.Combine(Tooling.Root(), "templates/space-program-v1.html"), 128 * 1024).Replace("$reports", string.Join("\n", cards)); if (a.Has("--refresh")) File.WriteAllText(output, page); else Tooling.WriteNew(output, page); Console.WriteLine($"Indexed {cards.Count} mission reports."); return 0; }
    internal static IEnumerable<(string Folder, JsonObject Data)> Reports(string archive) { foreach (var path in Directory.EnumerateFiles(archive, "manifest.json", SearchOption.AllDirectories).Order()) { var folder = Path.GetDirectoryName(path)!; var data = Tooling.ReadObject(path, 256 * 1024); if (data["schema"]?.ToString() == "ksp-continuum-chronicle-manifest/v1" && File.Exists(Path.Combine(folder, "index.html"))) yield return (folder, data); } }
}

internal static class SpaceProgramCommand
{
    public static int Run(string[] args) { var a = new Arguments(args); var archive = Path.GetFullPath(a.Required("--archive")); var catalogPath = Path.GetFullPath(a.Required("--catalog")); var output = Path.GetFullPath(a.Required("--output")); Tooling.Require(Path.GetDirectoryName(output) == archive, "output must be a direct child of the archive"); Tooling.Require(!Directory.Exists(output) && !File.Exists(output), "output already exists"); var catalog = Tooling.ReadObject(catalogPath, 1024 * 1024); Tooling.Require(catalog["schema"]?.ToString() == "ksp-continuum-space-program/v1", "unsupported catalog schema"); var program = catalog["program"] as JsonObject ?? throw new ToolException("program must be an object"); var name = Tooling.Text(program["name"], "program name", 500); var reports = ChronicleIndexCommand.Reports(archive).GroupBy(x => x.Data["attemptId"]!.ToString()).Select(x => x.OrderByDescending(v => DateTimeOffset.Parse(v.Data["generatedUtc"]!.ToString())).First()).ToArray(); Directory.CreateDirectory(output); foreach (var kind in new[] { "missions", "vehicles", "sites", "experiments", "attempts" }) Directory.CreateDirectory(Path.Combine(output, kind)); var entityLinks = new List<string>(); foreach (var kind in new[] { "missions", "vehicles", "sites", "experiments" }) if (catalog[kind] is JsonArray entities) foreach (var node in entities.Cast<JsonObject>()) { var id = Tooling.Text(node["id"], kind + " id", 128); var title = Tooling.Text(node["name"], kind + " name", 500); File.WriteAllText(Path.Combine(output, kind, id + ".html"), Page(name, $"<h1>{Tooling.Html(title)}</h1><p>{Tooling.Html(node["summary"]?.ToString())}</p>", "../")); entityLinks.Add($"<a href=\"{kind}/{id}.html\">{Tooling.Html(title)}</a>"); } foreach (var report in reports) { var id = report.Data["attemptId"]!.ToString(); var folder = Path.Combine(output, "attempts", id); Directory.CreateDirectory(folder); var original = File.ReadAllText(Path.Combine(report.Folder, "index.html")); var back = Path.GetRelativePath(folder, Path.Combine(report.Folder, "index.html")).Replace(Path.DirectorySeparatorChar, '/'); original = original.Replace("<body>", $"<body><nav class=\"site-nav\"><a href=\"../../index.html\">Program</a> · <a href=\"{back}\">Original report</a></nav>"); File.WriteAllText(Path.Combine(folder, "index.html"), original); var sourceMedia = Path.Combine(report.Folder, "media"); if (Directory.Exists(sourceMedia)) CopyDirectory(sourceMedia, Path.Combine(folder, "media")); if (File.Exists(Path.Combine(report.Folder, "telemetry.html"))) File.Copy(Path.Combine(report.Folder, "telemetry.html"), Path.Combine(folder, "telemetry.html")); } File.WriteAllText(Path.Combine(output, "index.html"), Page(name, $"<h1>{Tooling.Html(name)}</h1><div>{string.Join(" · ", entityLinks)}</div>" + string.Join("", reports.Select(x => $"<article><a href=\"attempts/{x.Data["attemptId"]}/index.html\">{Tooling.Html(x.Data["title"]?.ToString())}</a></article>")), "")); var marker = new JsonObject { ["schema"] = "ksp-continuum-space-program-site/v1", ["attempts"] = reports.Length, ["catalogSha256"] = Tooling.Sha256(catalogPath), ["generatorSha256"] = Tooling.Sha256(typeof(SpaceProgramCommand).Assembly.Location), ["reports"] = new JsonArray(reports.Select(x => (JsonNode)new JsonObject { ["attemptId"] = x.Data["attemptId"]!.ToString(), ["sourceFolder"] = Path.GetFileName(x.Folder) }).ToArray()) }; File.WriteAllText(Path.Combine(output, "site-manifest.json"), marker.ToJsonString(Tooling.Json) + "\n"); Console.WriteLine("Wrote connected space program site to " + output); return 0; }
    private static string Page(string program, string content, string prefix) => $"<!doctype html><html><head><meta charset=\"utf-8\"><title>{Tooling.Html(program)}</title></head><body><nav class=\"site-nav\"><a href=\"{prefix}index.html\">Program</a></nav><main>{content}</main></body></html>";
    private static void CopyDirectory(string source, string destination) { Directory.CreateDirectory(destination); foreach (var file in Directory.EnumerateFiles(source)) File.Copy(file, Path.Combine(destination, Path.GetFileName(file))); }
}

internal static class QualificationReportCommand
{
    public static int Run(string[] args) { var a = new Arguments(args); var source = Path.GetFullPath(a.Positional(0, "source")); var output = Path.GetFullPath(a.Required("--output")); Tooling.Require(Directory.Exists(source), "source directory does not exist"); Tooling.Require(!Directory.Exists(output) && !File.Exists(output), "output already exists"); var statusPath = Path.Combine(source, "status.txt"); var scopePath = Path.Combine(source, "scope.txt"); Tooling.Require(File.Exists(statusPath) && File.Exists(scopePath), "qualification source lacks scope or status"); var status = File.ReadLines(statusPath).FirstOrDefault()?.Trim() ?? throw new ToolException("empty status"); var phases = new JsonArray(); foreach (var marker in Directory.EnumerateFiles(source, "*-markers.json").Order()) { var data = Tooling.ReadObject(marker, 8 * 1024 * 1024); phases.Add(new JsonObject { ["phase"] = Path.GetFileName(marker)[..^"-markers.json".Length], ["status"] = data["status"]?.DeepClone(), ["requestedFrames"] = data["requestedFrames"]?.DeepClone(), ["completedFrames"] = data["completedFrames"]?.DeepClone(), ["markers"] = data["markers"]?.DeepClone(), ["playerLoop"] = data["playerLoop"]?.DeepClone(), ["partForces"] = data["partForces"]?.DeepClone() }); } Tooling.Require(phases.Count > 0, "qualification source has no phase markers"); var files = new JsonArray(); foreach (var path in Directory.EnumerateFiles(source).Order()) { var info = new FileInfo(path); Tooling.Require(info.LinkTarget is null && info.Length <= 16 * 1024 * 1024, "unsafe qualification source"); files.Add(new JsonObject { ["name"] = info.Name, ["bytes"] = info.Length, ["sha256"] = Tooling.Sha256(path) }); } var summary = new JsonObject { ["schema"] = "ksp-continuum-qualification-summary/v1", ["status"] = status, ["phases"] = phases, ["sources"] = files }; Directory.CreateDirectory(output); Tooling.WriteJsonNew(Path.Combine(output, "summary.json"), summary); var markerNames = string.Join("", phases.SelectMany(p => (p!["markers"] as JsonArray ?? []).Select(m => $"<li>{Tooling.Html(m!["name"]?.ToString())}: {Tooling.Html(m["status"]?.ToString())}</li>"))); Tooling.WriteNew(Path.Combine(output, "index.html"), $"<!doctype html><html><head><meta charset=\"utf-8\"><title>Qualification report</title></head><body><h1>Qualification report</h1><p>Status: {Tooling.Html(status)}</p><ul>{markerNames}</ul></body></html>"); Console.WriteLine("Wrote qualification report to " + output); return 0; }
}

internal static class ShadowReportCommand
{
    public static int Run(string[] args) { var a = new Arguments(args); var input = a.Required("--input"); var output = a.Required("--output"); var raw = File.ReadAllBytes(input); Tooling.Require(raw.Length <= 4 * 1024 * 1024, "input exceeds 4 MiB"); var data = JsonNode.Parse(raw) as JsonObject ?? throw new ToolException("expected JSON object"); var schema = data["schema"]?.ToString(); Tooling.Require(schema is "ksp-continuum-flight-shadow/v1" or "ksp-continuum-flight-shadow/v2", "unsupported schema"); var samples = data["samples"] as JsonArray ?? throw new ToolException("invalid samples"); var compared = samples.Cast<JsonObject>().Where(x => x["comparisonStatus"]?.ToString() == "compared").ToArray(); var report = new JsonObject { ["schema"] = "ksp-continuum-shadow-summary/v1", ["sourceSha256"] = Convert.ToHexString(SHA256.HashData(raw)).ToLowerInvariant(), ["sourceSchema"] = schema, ["status"] = data["status"]?.DeepClone(), ["sampleCount"] = samples.Count, ["comparedSamples"] = compared.Length, ["positionResidualMeters"] = Residual(compared, "observedPositionMaxMeters", "observedPositionRmsMeters"), ["velocityResidualMetersPerSecond"] = Residual(compared, "observedVelocityMaxMetersPerSecond", "observedVelocityRmsMetersPerSecond"), ["strategy"] = data["strategy"]?.DeepClone(), ["interpretation"] = "observed shadow residuals; no solver equivalence claim" }; Tooling.WriteJsonNew(output, report); return 0; }
    private static JsonNode? Residual(JsonObject[] samples, string maximum, string rms) { if (samples.Length == 0) return null; var values = samples.Select(x => (Max: Tooling.Finite(x[maximum], maximum), Rms: Tooling.Finite(x[rms], rms), Bodies: x["bodies"]?.GetValue<int>() ?? 1)).ToArray(); var count = values.Sum(x => x.Bodies); return new JsonObject { ["maximum"] = values.Max(x => x.Max), ["rms"] = Math.Sqrt(values.Sum(x => x.Rms * x.Rms * x.Bodies) / count), ["comparedBodies"] = count }; }
}
